entries[209954] = { ["name"] = "Moraghs Lieblingsstein", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+505 Stärke\nAnlegen: Eure Nahkampfangriffe haben eine Chance, 69033 Naturschaden zu verursachen, der unter dem Ziel und Gegnern in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich pro getroffenem Gegner bis für zu 5 Gegner.\nVerkaufspreis:" }
entries[209955] = { ["name"] = "Wurzel des Feuers", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 577.\nAnlegen: Erlittener Schaden und Nahkampfangriffe können Euch mit feurigen Dornen überziehen, die 1726 Stärke gewähren und den durch Gegner erlittenen Schaden 9 Sek. lang um 1175 verringern.\nVerkaufspreis:" }
entries[209956] = { ["name"] = "Oris tiefgrüne Feder", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 577.\nAnlegen: Zauber und Fähigkeiten, die Schaden verursachen, haben eine Chance, Euch 7 Sek. lang 1515 Beweglichkeit und 457 Geschwindigkeit zu gewähren.\nVerkaufspreis:" }
entries[209957] = { ["name"] = "Reißzahn der rasenden Nachtkralle", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+505 Beweglichkeit\nAnlegen: Zauber und Fähigkeiten, die Schaden verursachen, haben eine Chance, eine Nachtkralle zu rufen, die Euer Ziel ausweidet. Verursacht 59171 körperlichen Schaden und im Verlauf von 5 Sek. weitere ( 8284 * 5) körperlichen Schaden.\nVerkaufspreis:" }
entries[209958] = { ["name"] = "Rune der Umbramähne", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\n+505 Intelligenz\nAnlegen: Zauber und Fähigkeiten haben eine Chance, das Ziel in Mondlicht zu hüllen und einem Gegner 41419 Arkanschaden zuzufügen oder einen Verbündeten um 62172 Gesundheit zu heilen.\nVerkaufspreis:" }
entries[209959] = { ["name"] = "Eine Prise Traummagie", ["text"] = "Wird beim Anlegen gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 577.\nAnlegen: Zauber und Fähigkeiten haben eine Chance, 1645 Intelligenz zu gewähren und Eure Gestalt zu wandeln. (10s Abklingzeit)\nVerkaufspreis:" }
