entries[209996] = { ["name"] = "Haltespulenrune", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Belegt Euch selbst mit 'Haltespulenentzug', indem Ihr Euch an eine beliebige seltene Kreatur im Smaragdgrünen Traum bindet.\n\nSeltene Kreaturen zu besiegen, während 'Haltespulenentzug' aktiv ist, gewährt 'Straffe Haltespule'. (5 Sek. Abklingzeit)\n\"Lydiaras Rune, mit der von mächtigen Kreaturen im Smaragdgrünen Traum straffe Haltespulen gewonnen werden können.\"" }
entries[209997] = { ["name"] = "Destilliertes Wissen der Zeitwege", ["text"] = "Wird an Kriegsmeute gebunden\nEinzigartig (5)\nBenutzen: Erhöht die durch das Töten von Monstern und das Abschließen von Quests erhaltene Erfahrung um 5%.\n\nDer Abschluss eines Zeitwanderungsdungeons verstärkt den Effekt und setzt die Dauer zurück.\n\nBeim Erreichen von 4 Anwendung(en), erfolgt eine Umwandlung zu ' Meister der Zeitwege ', was den Effekt auf 30% erhöht." }
entries[209998] = { ["name"] = "Lydiaras Bindungsrune", ["text"] = "Wird beim Aufheben gebunden\n\"In Zusammenarbeit mit Lydiara Flüsterfeder gefertigt.\"" }
entries[209999] = { ["name"] = "Lydiaras Rune der Schattenbindung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bindet Euch an Knorrenwurzel, Igira oder Volcoross, um schattengebunden zu werden.\n\nWährend der 'Schattenbund' besteht, seid Ihr mit 'Lodernde Schattenflamme' belegt, was Euch abhängig von Eurer Entfernung zum Ziel um 0-50% verlangsamt und wodurch alle 5 Sek. die Chance besteht, Eure Mobilität einzuschränken. (5 Sek. Abklingzeit)\n\"Eine Rune der Schattenbindung, die auf Fyr'alath eingestimmt werden kann.\"" }
entries[210001] = { ["name"] = "Ordungspergamentprototyp", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Pergamentprototyp, das Shalasar aus leuchtenden Ascheflocken hergestellt hat.\"" }
entries[210002] = { ["name"] = "Aschene Wünschelrute", ["text"] = "Questgegenstand\nBenutzen: Entzieht Waffen oder Rüstungen von mächtiger (EPISCH) Qualität leuchtende Ascheflocken. Der anvisierte Gegenstand wird ZERSTÖRT und kann nicht zurückgeholt werden. (5 Min Abklingzeit)\n\"Eine Wünschelrute, die dem Benutzer die Fähigkeit verleiht, mächtige Ausrüstungsgegenstände zu entzaubern, um leuchtende Ascheflocken zu erhalten.\"" }
entries[210003] = { ["name"] = "Shalasars weises Pergament", ["text"] = "Wird beim Aufheben gebunden\n\"In Zusammenarbeit mit Shalasar Glimmerstaub gefertigt.\"" }
entries[210005] = { ["name"] = "10.2 Monster - Weapon - Staff - 10.1.5 Weapon Staff - Staff_2H_Druid_C_02_Color1", ["text"] = "Wird beim Anlegen gebunden\nZweihändig Stab\n7 - 10 Schaden Geschwindigkeit 3.60\n(2.4 Schaden pro Sekunde)\n+28 Intelligenz\n+9 Ausdauer\nErhöht Eure kritische Trefferwertung um + 8.\nErhöht Eure Tempowertung um + 5.\nVerkaufspreis:" }
entries[210008] = { ["name"] = "Schwelende Rune der Bindung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Möge das Feuer die Hindernisse auf Eurem Weg tilgen!\"\nPromotion:\nCataclysm Classic" }
entries[210009] = { ["name"] = "Traumlaubgriffprototyp", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Runenprototyp, den Erden aus ledrigem Schattentraumlaub gefertigt hat.\"" }
entries[210010] = { ["name"] = "Erdens Notizen zu symbiotischen Sporen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teile Erdens Notizen mit einem verbündeten Lederverarbeiter und bringe ihm vorübergehend bei, wie man Erdens Traumlaubgriff herstellt. Der Lederverarbeiter muss sich in der gleichen Gruppe befinden. (30 Min Abklingzeit)\n\"Notizen zu den Anforderungen für die Herstellung eines experimentellen symbiotischen Leuchtsporengriffs. Geschrieben von Lederverarbeitungsmeister Erden.\"" }
entries[210011] = { ["name"] = "Shalasars Notizen zu weiser Magie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teile Shalasars Notizen mit einem verbündeten Verzauberer und bringe ihm vorübergehend bei, wie man Shalasars weises Pergament herstellt. Der Verzauberer muss sich in der gleichen Gruppe befinden. (30 Min Abklingzeit)\n\"Notizen zu den Anforderungen für die Herstellung eines experimentellen weisen Pergaments. Geschrieben von Meisterverzauberin Shalasar Glimmerstaub.\"" }
entries[210012] = { ["name"] = "Erdens symbiotischer Leuchtsporengriff", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versucht, den symbiotischen Leuchtsporengriff an Fyr'alath zu binden, wobei Ihr 10 Sek. lang pro Sekunde Schattenflammenschaden in Höhe von 10-25% Eurer maximalen Gesundheit erleidet. (30 Sek. Abklingzeit)\n\"Ein ungetesteter Leuchtsporengriff\"" }
entries[210014] = { ["name"] = "Geheimnisvolle zeitlose Samen", ["text"] = "Questgegenstand\nEinzigartig (20)\nBenutzen: Pflanzt einen Samen der passenden Größe in einem Bereich mit Traumsaaterde in der Nähe.\n\"Traumsaat, die darauf wartet, erweckt zu werden.\"" }
entries[210016] = { ["name"] = "Schleier der Schlummereule", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Geht in Verstohlenheit über. Der Beginn eines Kampfs und der Einsatz von Fähigkeiten beenden den Effekt. Gegner entdecken Euch, wenn Ihr Euch zu sehr nähert. (8 Sek. Abklingzeit)\n\"Ruft Schlummereule Bodwin an, damit er Euch eine vorübergehende Verstohlenheitsaura verleiht.\"" }
entries[210017] = { ["name"] = "Fungusfisch", ["text"] = "Fungusphantasterei\n\"Einzahn behauptet, es sei ein Fisch, aber es sieht eigentlich eher wie ein halbgegessener Pilz aus.\"" }
entries[210020] = { ["name"] = "Handschutz des donnernden Sturmreiters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHände Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[210021] = { ["name"] = "Brustplatte des donnernden Sturmreiters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[210022] = { ["name"] = "Mimirons Sprungdüsen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Als Prototyp von Mimiron erschaffen. Die Teile wurden aus seiner Werkstatt gestohlen, verkauft und gingen über die Zeit verloren. Bis jetzt...\"\nWeltereignis:\nGeheimnisse von Azeroth" }
entries[210023] = { ["name"] = "Pergamentfetzen", ["text"] = "Questgegenstand\n\"Eine Notiz, die Aufschluss darüber geben könnte, wie der Prophet der Flamme unsere Verstärkungen aufhält.\"" }
entries[210024] = { ["name"] = "Ensemble: Zeitliche Lasten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Schulterrüstungsvorlagen, die Chromie und Morchie nutzen.\n\"Embleme der ewigen und bronzenen Drachenschwärme, passend für die Schultern.\"" }
