entries[210041] = { ["name"] = "Warenlieferung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\n\"Eine Kiste mit nützlichen Waren, die mit der Hilfe von Vashonir für die Traumwächter vorbereitet wurden. Eran'nda wird diese Vorratslieferungen gern annehmen.\"" }
entries[210042] = { ["name"] = "Frostiges Feierbanner", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Stellt Euer frostiges Feierbanner auf. (3 Min Abklingzeit)\n\"Das coolste Banner, das Ihr je gesehen habt.\"" }
entries[210048] = { ["name"] = "Shalasars weises Pergament", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Versucht, Fyr'alath mit Shalasars weisem Pergament zu verzaubern. Die Verzauberung wird nicht funktionieren, aber es könnte helfen, die Ordnungsmagie zu einem nutzbaren Zustand zu konzentrieren. (5 Min Abklingzeit)\n\"In Zusammenarbeit mit Shalasar Glimmerstaub gefertigt. Bereit, auf Fyr'alath eingestimmt zu werden.\"" }
entries[210049] = { ["name"] = "Die Legende von Elun'Ahir", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wie bei uralten Mythen üblich sind die Einzelheiten dieser Geschichte oft umstritten.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
