entries[210057] = { ["name"] = "Zügel des Morgenblütentraumsäblers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Traumwächtern.\nVerkaufspreis:\n\"Bekannt für die überschwängliche Energie, die von ihnen ausgeht, sind diese Säbler berüchtigte Trickser. Ihr Brüllen verscheucht die frühen Vögel, deren Gezwitscher sie weckt.\"\nVerkäufer:\nTalisa Flüsterblüte\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210058] = { ["name"] = "Zügel des Abendsonnentraumsäblers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Traumwächtern.\nVerkaufspreis:\n\"Diese Traumsäbler sind wilde Kämpfer, wobei sie dennoch oft dabei gesehen werden können, wie sie faul und ausgestreckt auf offenem Feld liegen. Nach einem ausgelassenen Bad in der Wärme des Tageslichts, brennen ihre Flammen umso heller.\"\nVerkäufer:\nTalisa Flüsterblüte\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210059] = { ["name"] = "Zügel des Winternachttraumsäblers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese nachtaktiven Traumsäbler tragen die Kälte des Winters in sich und schlafen oft tagelang, wenn sie nicht anderweitig geweckt werden.\"\nBeute von:\nTraumsaattruhe\nZone:\nSmaragdgrüner Traum" }
entries[210060] = { ["name"] = "Zügel des Schattendämmertraumsäblers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Ein Traumsäbler schlägt schnell aus den Schatten zu, schnappt sich kleinere Tiere und verschwindet dann wieder in der Dunkelheit, ohne dabei ein Geräusch zu machen. Die wenigen Glücklichen, die einen Traumsäbler beim Essen bestaunen konnten, haben dabei gesehen, wie sie vor dem Mahl noch genüsslich mit ihrer Beute spielen.\"\nErfolg:\nRuhm des Traumschlachtzüglers\nKategorie:\nDungeons & Schlachtzüge" }
entries[210061] = { ["name"] = "Zügel von Anu'relos, Wegweisung der Flamme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört Anu'relos, Wegweisung der Flamme, und gibt sie wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Obwohl ihre Federn mit zerstörerischen Flammen bedeckt zu sein scheinen, verbrennen sie einen nicht, sondern geben lediglich eine angenehme Wärme ab.\"\nBeute von:\nFyrakk\nZone:\nAmirdrassil, Hoffnung des Traums (Mythisch)" }
