entries[210136] = { ["name"] = "Entwurzelter Aschphodill", ["text"] = "Questgegenstand\n\"Von den Wurzeln flackern rauchende Irrwische auf, während glutheiße Pollen von der Spitze der Blume sprühen.\"" }
entries[210141] = { ["name"] = "Braunfelliger stachliger Bakar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Was für ein guter Junge. Oder Mädchen. Ist manchmal schwer auszumachen, aber immer gut.\"\nHandelsposten" }
entries[210142] = { ["name"] = "Leine des guten Jungen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Ihr müsst nicht die Erwartungen der ganzen Welt erfüllen. Seid, wer Taivan weiß, was Ihr sein *könnt*.\"\nErfolg:\nEine erweckte Welt\nKategorie:\nErweiterungsfeatures" }
entries[210148] = { ["name"] = "Überquellendes Säckchen gestohlener Rezepte", ["text"] = "\"Igira hat eine gigantische Sammlung von Rezepten angelegt, die aus dem Gewölbe der Inkarnationen und Aberrus, Schmelztiegel der Schatten, stammen.\"" }
