entries[210174] = { ["name"] = "Formel: Illusorische Verzierung: Träume", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Illusorische Verzierung: Träume' durchführt.\nErfüllt Schulterrüstung vorübergehend mit einer Illusion des Traums für [Quellwert] cd\nBenötigt Verzauberkunst der Dracheninseln (25)\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[210175] = { ["name"] = "Formel: Waffe - Träumende Hingabe", ["text"] = "Benutzen: Lehrt Euch, wie man die Verzauberung 'Träumende Hingabe' durchführt.\nVerzaubert eine Waffe dauerhaft, sodass sie manchmal die Macht des Traumes kanalisiert. Eure hilfreichen Zauber lassen möglicherweise eine magische Blume in der Nähe Eures Ziels gedeihen, die Verbündete in der Nähe um 14168 Gesundheit heilt. Kann nicht auf Gegenstände unter Stufe 180 angewendet werden.\nBenötigt Verzauberkunst der Dracheninseln (50)\nVerkaufspreis:" }
entries[210176] = { ["name"] = "Q'onzus Sichttalisman", ["text"] = "Questgegenstand\nBenutzen: Ermöglicht Euch das Aufspüren von aschegeladenen Wildtieren innerhalb von 40 Metern in den Verzweigten Wurzellanden. (5 Sek. Abklingzeit)" }
entries[210180] = { ["name"] = "Smaragd-Flugstein", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält 100 Flugsteine.\"\n<Zum Öffnen rechtsklicken>" }
entries[210181] = { ["name"] = "Unterzeichnete Arbeitsaufträge", ["text"] = "Questgegenstand\n\"Eine lange Liste von Konstrukteursmaterialien, die Kristallschmied Laharu Ataanya schuldet, von ihm persönlich gestempelt.\"" }
entries[210184] = { ["name"] = "Halbvoller Trank des traumlosen Schlafs", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Alchemie der Dracheninseln\n(25)\n\"Hier ist es wesentlich einfacher, es einfach \"Wasser\" zu nennen.\"" }
entries[210185] = { ["name"] = "Spritztrank der Narkolepsie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Alchemie der Dracheninseln\n(25)\n\"Das Ziel ist ja offensichtlich, Gegner einschlafen zu lassen, daher erscheint es kontraproduktiv, sie dabei zu bespritzen.\"" }
entries[210189] = { ["name"] = "Exarch Hataarus Handwerkslinse", ["text"] = "Questgegenstand\n\"Eine kleine, goldene Linse, getrübt von Alter und Nutzung. Die präzise geschliffenen Facetten erlauben Konstrukteuren, die Energiekanäle zu sehen, die durch die Kristalle strömen, mit denen sie arbeiten.\"" }
entries[210190] = { ["name"] = "Brandwurzel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Alchemiewissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Alchemie der Dracheninseln\n(25)\n\"Qualmt in Eurer Hand. Es wäre ein fantastischer Katalysator für Eure Gebräue, aber viel Glück dabei, Kräuterkundige davon zu überzeugen, die Hand dafür ins Feuer zu legen.\"" }
entries[210193] = { ["name"] = "Experimenteller Traumfänger", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Einen Magneten in den Smaragdgrünen Traum zu bringen, macht diesen nicht direkt zu einem Traumfänger, aber irgendjemand musste es versuchen.\"" }
entries[210194] = { ["name"] = "Schlaflositron", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Ein sorgfältig kalibriertes Gerät, das ein hohes Geräusch erzeugt, das nur schlafende Druiden hören können.\"" }
entries[210197] = { ["name"] = "Ungeschlüpfte Batterie", ["text"] = "Wird beim Aufheben gebunden\nDauer: 3 tagen\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Dies wurde anscheinend für ein verlegtes Ei gehalten, doch kann man sich durchaus fragen, was geschlüpft wäre, wenn die Brut nicht unterbrochen worden wäre.\"" }
entries[210198] = { ["name"] = "Erschöpfte Batterie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Ingenieurskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Ingenieurskunst der Dracheninseln (25)\n\"Was habt Ihr denn erwartet?\"" }
entries[210199] = { ["name"] = "Ausgefranstes Traumlaub", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Teilt ausgefranstes Traumlaub mit einem verbündeten Gruppenmitglied, damit es Euch bei der Suche nach mehr Schattentraumlaub helfen kann.\n\"Überrest eines Schattentraumlaubs.\"" }
entries[210200] = { ["name"] = "Versteinerte Hoffnung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Juwelierskunst der Dracheninseln\n(25)\n\"Ein makelloser Edelstein, geboren aus der Hülle eines gründlich entweihten Baums.\"" }
entries[210201] = { ["name"] = "Handvoll winziger Kiesel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Juwelierskunst der Dracheninseln\n(25)\n\"Einfache Steine, nur von Wert als Erinnerung an die Zeit, als Ihr ein paar Steine von einer Statue gekratzt habt.\"" }
entries[210202] = { ["name"] = "Verschmolzener Traumstein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Juwelierskunstwissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Juwelierskunst der Dracheninseln\n(25)\n\"Eine unglaubliche Leistung der Juwelierskunst, die eine beeindruckende Ähnlichkeit zu Eurem eigenen, hochgelobten Handwerk aufweist. Wie ist sie nur hier gelandet?\"" }
