entries[210207] = { ["name"] = "Ermächtigter regenerativer Symbiont", ["text"] = "Questgegenstand\n\"Die Leuchtsporensymbionten werden stärker.\"" }
entries[210208] = { ["name"] = "Büschel Traumsäblerfell", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Lederverarbeitungswissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Lederverarbeitung der Dracheninseln (25)\n\"Die Probe ist zwar zu klein, um irgendwas damit anzustellen, aber dieses Stück Traumsäblerfell eignet sich gut, die faszinierenden Eigenschaften des Materials zu studieren.\"" }
entries[210211] = { ["name"] = "Abgeworfene Feendrachenschuppen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Lederverarbeitungswissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Lederverarbeitung der Dracheninseln (25)\n\"Schimmernde und schillernde Schuppen, die für dekorative Rüstung genutzt werden könnten. Allerdings würden sie im Kampf keine guten Dienste leisten.\"" }
entries[210214] = { ["name"] = "Ouroborealische Halskette", ["text"] = "Wird beim Aufheben gebunden\nHals\n+1.197 Ausdauer\nErhöht Eure kritische Trefferwertung um + 360.\n+ 1.442 Vielseitigkeit\nAnlegen: Das Verursachen von Feuerschaden gewährt Euch einen Schild, der 56615 Naturschaden absorbiert. Das Verursachen von Naturschaden gewährt Euch einen Schild, der 56615 Feuerschaden absorbiert. Dieser Effekt kann nur einmal pro Minute ausgelöst werden. (1Min. Abklingzeit)\nVerkaufspreis:" }
entries[210215] = { ["name"] = "Traumkrallenklaue", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Studieren, um Euer Lederverarbeitungswissen der Dracheninseln um 3 zu erhöhen.\nBenötigt Lederverarbeitung der Dracheninseln (25)\n\"Außerordentlich scharf, bemerkenswert stabil und immer noch in fantastischem Zustand! Allerdings klebt ein bisschen Baumrinde dran.\"" }
entries[210217] = { ["name"] = "Kleine Traumgabe", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält einen einzigartigen kosmetischen Gegenstand oder eine kleine Menge an Berufsreagenzien.\"\n<Zum Öffnen rechtsklicken>" }
