entries[210219] = { ["name"] = "Gigantische Traumgabe", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält ein einzigartiges Reittier oder eine große Menge an Berufsreagenzien.\"\n<Zum Öffnen rechtsklicken>" }
