entries[210221] = { ["name"] = "Wappenbuch des geschmiedeten Kämpfers", ["text"] = "The War Within – Saison 1\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Zertifiziert hergestellte Ausrüstung für PvP-Schlachtfelder und erlaubt Skalierung auf Ggst. 613.\n\nHerstellungsverfahren benötigen mehrere.\n\"Erhältlich durch PvP-Aktivitäten und für Ehrenpunkte bei PvP-Rüstmeistern in Dornogal. Kann im Auktionshaus verkauft und erworben werden.\"" }
entries[210222] = { ["name"] = "Gelöstes Element", ["text"] = "Questgegenstand\n\"Ein gebändigtes Element, das wieder an das konzentrierte weise Pergament gebunden werden kann.\"" }
entries[210223] = { ["name"] = "Instabiles Element", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Bringt das stabilisierte Element zum Träger von Fyr'alath zurück.\n\"Ein Element, das noch stabilisiert werden muss.\"\nVerkaufspreis:" }
entries[210224] = { ["name"] = "Kleine Smaragdblüte", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält eine kleine Menge Vorräte der Dracheninseln und Flugsteine. Beinhaltet eine winzige Chance, das Reittier Winternachttraumsäbler zu erhalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[210225] = { ["name"] = "Mittelgroße Smaragdblüte", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält eine mittlere Menge Vorräte der Dracheninseln und Flugsteine. Beinhaltet eine sehr geringe Chance, das Reittier 'Winternachttraumsäbler' zu erhalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[210226] = { ["name"] = "Große Smaragdblüte", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält eine große Menge Vorräte der Dracheninseln und Flugsteine. Beinhaltet eine geringe Chance, das Reittier 'Winternachttraumsäbler' zu erhalten.\"\n<Zum Öffnen rechtsklicken>" }
entries[210227] = { ["name"] = "Q'onzus Feenfeder", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wedelt mit Q'onzus Feenfeder, um Schotlinge in der Nähe, die unter 50% Gesundheit haben, in Feendrachen zu verwandeln. Vorsicht, das Ding hat jede Menge Auftrieb! (3 Sek. Abklingzeit)\n\"Eine kleine Feder von Q'onzu. Seltsamerweise hat sich ihr Muster zu dem eines Feendrachen geändert.\"" }
entries[210228] = { ["name"] = "Reines Traumwasser", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Verzauberkunst der Dracheninseln (25)\n\"Im Inneren lassen sich wertvolle magische Informationen finden. Entzaubern steigert das Verzauberkunstwissen.\"" }
