entries[210409] = { ["name"] = "Aura", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[210411] = { ["name"] = "Schnell wachsender Samen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Pflanzt einen Samen, der schnell wächst. (1 Min Abklingzeit)\n\"Ein Sprössling bricht seitlich aus dem Samen hervor, bereit, Wurzeln zu schlagen.\"\nVerkaufspreis:" }
entries[210412] = { ["name"] = "Blühender Launendrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren blühenden Launendrachen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese verspielten Beschützer des Smaragdgrünen Traums mögen größer als die mit ihnen artverwandten Feendrachen sein, aber sie sind dennoch nicht weniger schalkhaft.\"\nQuest:\nSmaragdgrünes Willkommen\nZone:\nDer Smaragdgrüne Traum" }
entries[210413] = { ["name"] = "Karte der Sicherheitseinrichtungen von Burg Schattenfang", ["text"] = "Questgegenstand\n80 ( 80)\n\"Auf dieser Karte sind die Basis der Chemiemanufaktur Krone und sämtliche Wachposten eingezeichnet.\"" }
