entries[210416] = { ["name"] = "Formel für berauschendes toxisches Parfüm", ["text"] = "Questgegenstand\n80 ( 80)\n\"Eine Formel, die die Zutaten und die Vorgehensweise zur Herstellung tödlicher Aromen enthält.\"" }
entries[210417] = { ["name"] = "Memo von Apotheker Hummel", ["text"] = "Questgegenstand\n80 ( 80)\n\"Eine Notiz, die in feiner, wenn auch leicht kratziger Schrift verfasst wurde.\"\n<Zum Lesen rechtsklicken>" }
