entries[210424] = { ["name"] = "Darnassischer Wappenrock", ["text"] = "Wird beim Aufheben gebunden\nWappenrock\nBenötigt eine Allianz-Rasse" }
entries[210430] = { ["name"] = "Verdrehte träumende Essenz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Sie wirbelt mit einer unheilvollen, gewalttätigen Intensität, die in dem Traum fehl am Platze zu sein scheint. Merithra würde das sicher interessieren.\"" }
entries[210431] = { ["name"] = "Handwerk-Bon-Bomben", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Fügt Mitgliedern der Chemiemanufaktur Krone innerhalb von 4 Metern 1278875 Feuerschaden zu und zerstört Materialien der Chemiemanufaktur Krone. (7 Sek. Abklingzeit)\n\"Hergestellt mit purer Liebe. Und Unmengen an Sprengpulver.\"\nVerkaufspreis:" }
entries[210432] = { ["name"] = "Hochlanddrache: Winterhauchrüstung", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den Hochlanddrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
