entries[210434] = { ["name"] = "Antlitz von Ursol", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"Ein längst vergessener Ritualkopfschmuck, der das Gesicht des weisen Bärenfürsten darstellt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[210435] = { ["name"] = "Wassertotem des Archivars", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört ein Wassertotem an Eure Position, um die Ausgrabung zu unterstützen. (5 Sek. Abklingzeit)" }
entries[210436] = { ["name"] = "Wiege der Natur", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Fügt einem Gegenstand der Saison 3 von Dragonflight, der noch keinen Sockel besitzt, einen hinzu. Kann auf Helme, Armschienen, Gürtel und Ringe angewandt werden." }
