entries[210453] = { ["name"] = "Eine Probe Glutpollen", ["text"] = "Questgegenstand\n\"Trotz der feuerresistenten Glutseide als Futter des Beutels könnt ihr ihn mit Glutpollen gefüllt vor Hitze kaum halten.\"" }
entries[210454] = { ["name"] = "Ersatzholoedelstein", ["text"] = "Questgegenstand\nBenutzen: Teleportiert Euch zu den Koordinaten, die im Holostein gespeichert sind. (30 Sek. Abklingzeit)\n1 Aufladung\n\"Ein verbreitetes Werkzeug der Draenei, das häufig zur Speicherung von Teleportationszaubern und zur Kommunikation über große Entfernungen genutzt wurde.\"" }
entries[210455] = { ["name"] = "Draenischer Holostein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\nNur Draenei und Lichtgeschmiedete Draenei können den draenischen Holostein verwenden.\n\"Ein verbreitetes Werkzeug der Draenei, das häufig zur Speicherung von Teleportationszaubern und zur Kommunikation über große Entfernungen genutzt wurde.\"" }
entries[210456] = { ["name"] = "Bruchstück eines träumenden Geweihs", ["text"] = "Handwerksmaterial\n\"Ein Bruchstück eines majestätischen Geweihs, das mit der Macht des Traums pulsiert. Wird nur selten beim Häuten eines scheuen tiefgrünen Hainwächters gefunden. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[210457] = { ["name"] = "Fischgräten", ["text"] = "Questgegenstand\n\"Diese dünnen, flexiblen Knochen sollten unter den richtigen Bedingungen leicht zerfallen.\"" }
