entries[210467] = { ["name"] = "Magischer Murkwandler", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Beschwört ein magisches Monument, das Euer Aussehen 20 Min. lang verändern kann. (1 Stunde Abklingzeit)\n\"Unter Murlocenthusiasten auch als Transmurk-Leuchtfeuer bekannt.\"" }
entries[210468] = { ["name"] = "Smaragdblüten-Traumstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erfüllt Eure Rüstung mit einem schwachen Echo der Macht des Smaragdgrünen Traums, was zusätzliche optische Effekte für bestimmte Klassensetvorlagen aus Amirdrassil, Hoffnung des Traums, freischaltet.\n\nDieser Effekt gilt für die gesamte Kriegsmeute." }
