entries[210572] = { ["name"] = "Truhe mit tiefgrüner Ausrüstung", ["text"] = "Saison 3 von Dragonflight\nWird an Kriegsmeute gebunden\nBenutzen: Erschafft ein Ausrüstungsteil des tiefgrünen Gladiators mit dem Rang 'Ungewertet', das für Eure Beutespezialisierung nützlich ist.\nErfordert eine PvP-Wertung von: 1.400 (beliebige Sparte)." }
entries[210575] = { ["name"] = "Hatuuns Gedächtnisstein", ["text"] = "Questgegenstand\n\"Jeden Morgen im Konservatorium. Vogelgesang.\"" }
entries[210576] = { ["name"] = "Romuuls Gedächtnisstein", ["text"] = "Questgegenstand\n\"Der Verteidigungskristall hatte einen kaputten Kondensator. Nur einen.\"" }
entries[210577] = { ["name"] = "Ataanyas Gedächtnisstein", ["text"] = "Questgegenstand\n\"Tintenflecken auf seinen Tentakeln, wo sie seine Baupläne berührten.\"" }
entries[210578] = { ["name"] = "Arzaals Gedächtnisstein", ["text"] = "Questgegenstand\n\"Ich wich vor ihrem Blut zurück, als es meine Hufe berührte.\"" }
entries[210579] = { ["name"] = "Boros' Gedächtnisstein", ["text"] = "Questgegenstand\n\"Es war leichter, von einem Planeten zu fliehen, als ihn zu verteidigen. Ich stimmte zu. Wieder und wieder.\"" }
entries[210580] = { ["name"] = "Nobundos Gedächtnisstein", ["text"] = "Questgegenstand\n\"In diesem Moment war ich leer. Ich wünschte mir, zu leben. Ich hoffte, zu sterben.\"" }
entries[210581] = { ["name"] = "Ishanahs Gedächtnisstein", ["text"] = "Questgegenstand\n\"Ich sah sein Gesicht, als ich aufwachte. Tränen standen in seinen Augen. Dann erlosch das Licht in ihnen.\"" }
entries[210582] = { ["name"] = "Jadaars Gedächtnisstein", ["text"] = "Questgegenstand\n\"Ich räumte die zertrümmerten Mauern fort. Dort waren Kinder.\"" }
entries[210583] = { ["name"] = "Kuros' Gedächtnisstein", ["text"] = "Questgegenstand" }
entries[210584] = { ["name"] = "Naielles Gedächtnisstein", ["text"] = "Questgegenstand\n\"Sie hatten Katapulte. Wir hätten ihre Spuren vor den Mauern sehen sollen.\"" }
entries[210585] = { ["name"] = "Aesoms Gedächtnisstein", ["text"] = "Questgegenstand" }
entries[210586] = { ["name"] = "Akamas Gedächtnisstein", ["text"] = "Questgegenstand\n\"Ich war etwas, nicht jemand. Ketten handeln, wieder und wieder.\"" }
entries[210587] = { ["name"] = "Nemuraans Gedächtnisstein", ["text"] = "Questgegenstand" }
entries[210588] = { ["name"] = "Omans Gedächtnisstein", ["text"] = "Questgegenstand\n\"Das Dahinscheiden von Hespera, verloren im Wrack der Genedar.\"" }
entries[210591] = { ["name"] = "Gedächtnisstein des Tishamaat", ["text"] = "Questgegenstand\n\"Ein glatter, faustgroßer Stein, der mit einer schmerzhaften Erinnerung beschrieben wurde. Er ist überraschend schwer.\"" }
