entries[210769] = { ["name"] = "Zügel der Springfluttraumkralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Traumwächtern.\nVerkaufspreis:\n\"Versprüht die Art Enthusiasmus und Energie, die jeden neidisch machen würde.\"\nVerkäufer:\nTalisa Flüsterblüte\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210770] = { ["name"] = "Beutel mit Traumwappen des Drachen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 Traumwappen des Drachen. Diese Wappen ignorieren das Saisonlimit.\nSchließt die Quest \"Wappentraum\" von Vaskarn im Zentrallager ab, um Eure Traumwappen abwerten zu können." }
entries[210774] = { ["name"] = "Zügel der ockerfarbenen Traumkralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Verspielte Traumkrallen verzieren sich oft selbst mit einer Fülle an Farben, wie sie nur die Herbstzeit zu bieten hat.\"\nQuest:\nEin bisschen Hoffnung ist immer gut\nZone:\nSmaragdgrüner Traum" }
entries[210775] = { ["name"] = "Zügel der schneeweichen Traumkralle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmrang 18 bei den Traumwächtern.\nVerkaufspreis:\n\"Unbeschwert und sanft wie Schnee können sie von einer Schneewehe zur nächsten hüpfen, ohne dabei Spuren zu hinterlassen.\"\nVerkäufer:\nTalisa Flüsterblüte\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210776] = { ["name"] = "Geringe Trauminfusion", ["text"] = "Wird an Kriegsmeute gebunden\n\"Ein leuchtend grüner Edelstein, der eine kleine Menge Traumenergie abgibt.\"" }
entries[210777] = { ["name"] = "Schlafi", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nIhr müsst eine Felsschnecke als Haustier in Eurer Sammlung haben, um eine neue mit Traumenergie zu erfüllen." }
entries[210778] = { ["name"] = "Windtotem des Archivars", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört ein Windtotem an Eure Position, um die Ausgrabung zu unterstützen. (5 Sek. Abklingzeit)" }
entries[210780] = { ["name"] = "Geringe Glut von Fyr'alath", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Empfangt die Glut und erhöht dadurch dauerhaft Eure Chance, Fyr'alath, den Traumreißer, zu erhalten.\n\"Die Hymne des Traumreißers ruft Euch aus dem Inneren.\"" }
entries[210782] = { ["name"] = "Schlummernder Mondfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Mondfisch in die Gewässer von Amirdrassil zurück. Verleiht einen Stapel Mondfischessenz.\n\"Dieser geisterhafte Fisch kommt nur in den Wassern von Amirdrassil vor. Der Fisch wird von Eurer Einstimmung auf den Smaragdgrünen Traum angezogen.\"\nVerkaufspreis:" }
entries[210783] = { ["name"] = "Erwachender Sonnenfisch", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Sonnenfisch in die Gewässer von Amirdrassil zurück. Verleiht einen Stapel Sonnenfischessenz.\n\"Dieser verspielte Fisch kann in glühend heißen Temperaturen überleben und ist nur in Amirdrassil anzutreffen. Er scheint von der inneren Verbindung zwischen Euch und dem Weltenbaum angezogen zu werden.\"\nVerkaufspreis:" }
entries[210784] = { ["name"] = "Xena, der wunderliche Schnurrwels", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Werft Xena zurück in die Gewässer von Amirdrassil.\n\"Xenas prismatische Schuppen reflektieren jegliche Form von Licht mit einem Leuchten, das nur als wunderlich bezeichnet werden kann.\"\nVerkaufspreis:" }
entries[210785] = { ["name"] = "Snorr", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)\nIhr müsst einen Wyvernwelpen als Haustier in Eurer Sammlung haben, um einen neuen mit Traumenergie zu erfüllen." }
entries[210786] = { ["name"] = "Träumender Schnurrwels", ["text"] = "Wird beim Aufheben gebunden\n\"Ein grünes Traumgefäß von einem verzierten Schnurrwels.\"" }
entries[210787] = { ["name"] = "Eleganter Wappenrock der grünen Drachen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[210788] = { ["name"] = "Eleganter Schal der grünen Drachen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[210789] = { ["name"] = "Elegante Schulterklappen der grünen Drachen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchulter Kosmetisch\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[210790] = { ["name"] = "Ensemble: Elegante Oberbekleidung der grünen Drachen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlage für das Set: Elegante Oberbekleidung der grünen Drachen.\nBenötigt Ruhmrang 16 bei den Traumwächtern." }
entries[210791] = { ["name"] = "Bruchstück von Glutnarbe", ["text"] = "Questgegenstand\n\"Ein von Glimmerons legendärer Waffe in Amirdrassil, Hoffnung des Traums, auf dem Schwierigkeitsgrad \"Normal\" entnommenes Bruchstück.\"" }
entries[210792] = { ["name"] = "Bruchstück von Glutnarbe", ["text"] = "Questgegenstand\n\"Ein von Glimmerons legendärer Waffe in Amirdrassil, Hoffnung des Traums, auf dem Schwierigkeitsgrad \"Heroisch\" entnommenes Bruchstück.\"" }
entries[210793] = { ["name"] = "Bruchstück von Glutnarbe", ["text"] = "Questgegenstand\n\"Ein von Glimmerons legendärer Waffe in Amirdrassil, Hoffnung des Traums, auf dem Schwierigkeitsgrad \"Mythisch\" entnommenes Bruchstück.\"" }
entries[210813] = { ["name"] = "Wilde Experimente", ["text"] = "\"Experimentiert mit instabilen Reagenzien in der Hoffnung, neue Rezepte zu entdecken.\"" }
entries[210814] = { ["name"] = "Händchen fürs Kunsthandwerk", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein geheimnisvolles Reagenz, das sich dem menschlichen Verstand entzieht und nur Meisterhandwerkern anvertraut wird. Es wird oft für hochwertige Herstellungs- und Umfertigungsverfahren eingesetzt, obwohl seine Wirkung nichts als Aberglaube ist.\"" }
entries[210815] = { ["name"] = "Kernwegkatalysator", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Als Nebenprodukt aus der Rückgewinnung von überschüssigen Mixturen erlangt.\"\nVerkaufspreis:" }
entries[210816] = { ["name"] = "Algarischer Alchemistenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar: Alchemistenstein (1)\nSchmuck\n+ 924 Vielseitigkeit\nAnlegen: Es besteht eine Chance, dass sich bei durch Euch hervorgerufene Heilung oder verursachter Schaden Eure Stärke, Beweglichkeit oder Intelligenz 15 Sek. lang um 5955 erhöht. Es wird stets Euer höchster Wert gewählt.\nAnlegen: Erhöht die Effekte, die Heil- und Manatränke auf den Träger haben, um 40%. Dieser Effekt ist nicht stapelbar.\n\"Kann anstelle eines Steins der Weisen für Transmutationen verwendet werden.\"\nVerkaufspreis:" }
entries[210819] = { ["name"] = "Kirschen mit Schokoladenüberzug", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 175 * 30 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Ausdauer und Vielseitigkeit.\nVerkaufspreis:" }
entries[210821] = { ["name"] = "Schokoladentarte mit Früchten", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 375 * 30 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 15 Min. lang 2 Ausdauer und Vielseitigkeit.\nVerkaufspreis:" }
entries[210826] = { ["name"] = "Erntebotreparaturset", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lernt die Grundlagen der Verwendung von strahlenden Überbleibseln zur Reparatur inaktiver Erntebots.\n\nNach der Reparatur helfen sie im Kampf gegen Gegner in ihrer Nähe.\n\"Ezgis Anweisungen und Werkzeuge zur Reparatur von Erntebots.\"\nVerkaufspreis:" }
entries[210827] = { ["name"] = "Egzis Gizmo", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (10)\nBenutzen: Ein Notsignal, das den verfügbaren Erntebot aktiviert, um den Stillsteintümpel und die Fackelscheinmine von Bedrohungen zu befreien.\nBenötigt Ruhmrang 12 bei den Arathi von Heilsturz.\n\"Wenn man erstmal gelernt hat, eins zu reparieren, dann ist der Rest ganz einfach!\"\nVerkaufspreis:" }
entries[210828] = { ["name"] = "Verdünnungslösung", ["text"] = "Wird beim Aufheben gebunden\nHandwerksmaterial\n\"Ein alchemistisches Reagenz, um die Effekte von Tränken und Fläschchen aufzuheben. Kann von Alchemiehändlern auf ganz Khaz Algar erworben werden.\"\nVerkaufspreis:" }
entries[210829] = { ["name"] = "Gebräue neutralisieren", ["text"] = "\"Extrahiert Kernwegkatalysatoren aus einer großen Menge an Tränken oder Fläschchen, die Ihr nicht mehr braucht.\"" }
entries[210830] = { ["name"] = "Fertige Rush'kah-Maske", ["text"] = "Questgegenstand\n80 ( 80)\n\"Eine neu hergestellte Rush'kah-Maske der Dunkelspeere.\"" }
entries[210831] = { ["name"] = "Truggeber", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst einen Ottuk als Reittier in Eurer Sammlung haben, um einen neuen mit Traumenergie zu erfüllen.\n\n\"Stellt Euch vor, so sehr in einen Traum versunken zu sein, dass er Euch real vorkommt. Manche würden sagen, er überschwemmt einen regelrecht.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210833] = { ["name"] = "Kraller", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst eine Traumkralle als Reittier in Eurer Sammlung haben, um eine neue mit Traumenergie zu erfüllen.\n\n\"Manche Tagträume stecken voller wunderbarer Möglichkeiten, zerbrechen jedoch, wenn sie an die Schranken der Realität erinnert werden. Doch manche Träume sind nicht ganz so belastet, selbst wenn sie jemanden auf dem Rücken tragen.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210834] = { ["name"] = "Erdtotem des Archivars", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört ein Erdtotem an Eure Position, um die Ausgrabung zu unterstützen. (5 Sek. Abklingzeit)" }
