entries[210841] = { ["name"] = "Gebutterte Austern", ["text"] = "Benutzen: Stellt im Verlauf von 20 Sek. Eure Gesundheit und Euer Mana vollständig wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet 1 Stunde lang Meisterschaft.\nVerkaufspreis:" }
