entries[210848] = { ["name"] = "Mitternachtssarong des Händers", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBeine Kosmetisch\n\"In mitternächtliche Farben gehüllt gleitet Ihr anmutig durch den Markt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
