entries[210864] = { ["name"] = "Improvisiertes Laubbett", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Wenn Ihr, egal, wo Ihr seid, Schlaf braucht. (20 Min Abklingzeit)\nVerkaufspreis:" }
entries[210865] = { ["name"] = "Karminsteine des Klingenmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\n\"Das Blut von Samuros Feinden passt gut zu den Steinen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[210866] = { ["name"] = "Sonnenberührte Steine des Klingenmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\n\"Aus den Hallen der Himmelsnadel. Diese Steine verliehen ihrem Träger das Feuer von Rukhmar.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[210867] = { ["name"] = "Lebhafte Steine des Klingenmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\n\"Diese Steine aus geglättetem Talasit wurden von Lantresor zurückerobert, nachdem er zum Anführer der Brennenden Klinge wurde.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[210868] = { ["name"] = "Violettasteine des Klingenmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\n\"Schüchtert Eure Gegner mit Eurem besten Aussehen ein.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[210869] = { ["name"] = "Azursteine des Klingenmeisters", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\n\"Steine, die Jubei im dritten Krieg trug.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
