entries[210871] = { ["name"] = "Große Glut von Fyr'alath", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Empfangt die Glut und erhöht dadurch dauerhaft Eure Chance, Fyr'alath, den Traumreißer, zu erhalten.\n\"Die Hymne des Traumreißers ruft Euch aus dem Inneren.\"" }
entries[210872] = { ["name"] = "Säckchen der Träume", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Enthält Geschenke der Traumwächter.\"\n<Zum Öffnen rechtsklicken>" }
entries[210873] = { ["name"] = "Identifikationsplakette der Irdenen", ["text"] = "Questgegenstand\n\"Darauf eingeprägt sind Kennzeichnung, Funktion und Datum des erstmaligen Erweckens eines gefallenen Maschinenflüsterers. Es folgt ein Eintrag für den Namen, der eindeutig zu einem späteren Zeitpunkt eingraviert wurde.\"" }
