entries[210917] = { ["name"] = "Beutel mit Traumwappen des verzauberten Welpen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 Traumwappen des Welpen. Diese Wappen ignorieren das Saisonlimit.\nSchließt die Quest \"Wappentraum\" von Vaskarn im Zentrallager ab, um Eure Traumwappen abwerten zu können." }
entries[210918] = { ["name"] = "Adaptive Kühlsalbe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Schmiert Eure Hände mit der Salbe ein, wodurch Ihr den symbiotischen Leuchtsporengriff sicher auf Fyr'alath einstimmen könnt, bevor die Salbe sich auflöst.\n3 Aufladungen\n\"Tragt diesen Balsam auf Eure Hände auf, bevor Ihr versucht, den symbiotischen Leuchtsporengriff für Fyr'alath zu vereinen.\"\nVerkaufspreis:" }
entries[210919] = { ["name"] = "Karmin Glimmerpelz", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört einen reitbaren scharlachroten Vulpin oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Gilnearischen Legenden zufolge durchquert dieser rotweiße Fuchs nur zu einer Jahreszeit den Winterhauch.\"\nHandelsposten" }
entries[210920] = { ["name"] = "Geschenk von Amirdrassil", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 2500 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)" }
