entries[210923] = { ["name"] = "Tasche mit Traumwappen des Wyrms", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 Traumwappen des Wyrms. Diese Wappen ignorieren das Saisonlimit.\nSchließt die Quest \"Wappentraum\" von Vaskarn im Zentrallager ab, um Eure Traumwappen abwerten zu können." }
entries[210926] = { ["name"] = "Paket mit Schokolade nur für mich, mich, mich", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 15 Sek. ( 630000 / 5 * 15) Gesundheit wieder her. Wenn Ihr mindestens 15 Sek. mit Essen verbringt, spürt Ihr die Liebe und für 2 Stunden wird Eure Moral gestärkt.\nBenötigt Liebe liegt in der Luft\n\"Eine Liebeserklärung an überzeugte Schokonascher.\"" }
entries[210927] = { ["name"] = "Fruchtiger Cocktailschwarm", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Ein starkes alkoholisches Getränk.\nBenötigt Liebe liegt in der Luft" }
entries[210928] = { ["name"] = "Paket mit gesundem Essen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 15 Sek. ( 630000 / 5 * 15) Gesundheit wieder her. Wenn Ihr mindestens 15 Sek. mit Essen verbringt, spürt Ihr die Liebe und für 2 Stunden wird Eure Moral gestärkt.\nBenötigt Liebe liegt in der Luft\n\"Eine echte Gaumenfreude für Obstliebhaber und Gesundheitsenthusiasten.\"" }
entries[210929] = { ["name"] = "Paket mit Trostessen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stellt im Verlauf von 15 Sek. ( 630000 / 5 * 15) Gesundheit wieder her. Wenn Ihr mindestens 15 Sek. mit Essen verbringt, spürt Ihr die Liebe und für 2 Stunden wird Eure Moral gestärkt.\nBenötigt Liebe liegt in der Luft\n\"Schmackhafte Leckerbissen für harte Tage.\"" }
entries[210939] = { ["name"] = "Nullstein", ["text"] = "Handwerksmaterial\n\"Wird manchmal von Spielercharakteren gesammelt, die den Beruf Bergbau ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[210944] = { ["name"] = "Smaragdmal der Meisterschaft", ["text"] = "Saison 3 von Dragonflight\nWird beim Aufheben gebunden\nEinzigartig\n\"Wird für außerordentliche Dienste an die Drachenspezies verliehen. Bringt es Theozhaklos dem Neugierigen am Urquellausguck im Smaragdgrünen Traum, um mächtige Ausrüstung für Eure Mühen zu erhalten.\"" }
entries[210945] = { ["name"] = "Sternstreifer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst einen Traumhirsch als Reittier in Eurer Sammlung haben, um einen neuen mit Traumenergie zu erfüllen.\n\n\"Wie es sich wohl anfühlt, die Sterne aus ihrer Verankerung am Himmel reißen zu können? Vielleicht wird Sternstreifer uns eines Tages zeigen, wie das geht.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210946] = { ["name"] = "Mammyth", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst ein Magmammut als Reittier in Eurer Sammlung haben, um ein neues mit Traumenergie zu erfüllen.\n\n\"Im Traum ist der Mythos manchmal realer als seine Grundlage.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210947] = { ["name"] = "Flammenverzerrte Kuriosität", ["text"] = "Wird beim Aufheben gebunden\n\"Eine Erinnerung an die feurige Zukunft, die Fyrakk vorschwebte. Kirasztia am Urquellausguck im Smaragdgrünen Traum weiß vielleicht, wie man die Geheimnisse darin freisetzt.\"\nVerkaufspreis:" }
entries[210948] = { ["name"] = "Gedankenschwinge", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst eine Schieferschwinge als Reittier in Eurer Sammlung haben, um eine neue mit Traumenergie zu erfüllen.\n\n\"Es gibt nichts Schöneres, als seine Gedanken fliegen zu lassen.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210950] = { ["name"] = "Einsicht von Q'onzu", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Verleiht die BESTE Menge Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)\n\"Wer braucht materiellen Besitz, wenn man Q'onzu erlebt hat?\"" }
entries[210951] = { ["name"] = "Trügerische Forschungsnotizen.", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 250 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)" }
entries[210952] = { ["name"] = "Spärlich erhitzter Ruhestein", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 500 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)\n\"Scheint nur gut fürs Heizen zu sein.\"" }
entries[210954] = { ["name"] = "Sprössling der Wiedergeburt", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 750 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)" }
entries[210956] = { ["name"] = "Feuertotem des Archivars", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Beschwört ein Feuertotem an Eure Position, um die Ausgrabung zu unterstützen. (5 Sek. Abklingzeit)\n\"Nur für besondere Anlässe.\"" }
