entries[210958] = { ["name"] = "Krone der Dryaden-Tochter", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 500 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)\n\"Aus den Blütenblättern giftiger Schotlinge gemacht. Eine süße Geste, die aber besser nicht getragen wird.\"" }
entries[210959] = { ["name"] = "Pakt der Netherschwingen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 750 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)" }
entries[210961] = { ["name"] = "Alara'shinu", ["text"] = "Wird beim Aufheben gebunden\nEinhändig Kriegsgleve\n686 - 1,086 Schaden Geschwindigkeit 2.60\n(340.8 Schaden pro Sekunde)\n+300 Beweglichkeit\n+1.064 Ausdauer\nErhöht Eure kritische Trefferwertung um + 194.\nErhöht Eure Meisterschaftswertung um + 237.\nHaltbarkeit 120 / 120\n\"Schönheit in der Unvollkommenheit finden.\"\nVerkaufspreis:" }
entries[210964] = { ["name"] = "Mini-Furorion", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[210965] = { ["name"] = "Einmalig verwendbarer Blumenstrauß", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Wirft den Blumenstrauß einem Freund oder einer Freundin zu. (5 Min Abklingzeit)" }
entries[210969] = { ["name"] = "Salaträumer", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nIhr müsst einen Salamanther als Reittier in Eurer Sammlung haben, um einen neuen mit Traumenergie zu erfüllen.\n\n\"Zwar wechselt die Aufmerksamkeit der meisten Salamanther ständig frei ihre Ausrichtung, aber dennoch genießt dieser es, seine Umgebung regungslos zu beobachten.\"\nVerkäufer:\nElianna\nZone:\nSmaragdgrüner Traum\nKosten:\n1" }
entries[210970] = { ["name"] = "Zerfallenes Andenken", ["text"] = "Fungusphantasterei\n\"Ein altes Erinnerungsstück, das bei dem Irdenen verbleiben sollte, dem es gehörte.\"" }
entries[210973] = { ["name"] = "Herzsuchermanarochen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen Herzsuchermanarochen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Jemand hat diesem Manarochen einmal gesagt, dass er so süß sei. Seitdem jagt er diesem guten Gefühl noch immer hinterher.\"\nWeltereignis:\nLiebe liegt in der Luft\nKosten:\n270" }
entries[210974] = { ["name"] = "Nur Augen für Euch", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Blendet alle aus, die nicht in Eurer Gruppe sind. (30 Min Abklingzeit)" }
entries[210975] = { ["name"] = "Datumssimulationsmodulator", ["text"] = "Wird bei Benutzung gebunden\nSpielzeug\nBenutzen: Platziert einen Datumssimulationsmodulator für bis zu 2 Stunden, mit dem Ihr die Welt aus einer anderen Perspektive sehen könnt.\n\nEin integrierter Tarnmechanismus sorgt dafür, dass nur Mitglieder Eurer Gruppe oder Eures Schlachtzugs das Gerät und seine Effekte sehen können.\n\nKann nur im Freien verwendet werden. (2 Std. Abklingzeit)\nVerkaufspreis:" }
entries[210977] = { ["name"] = "Gebündeltes Mondlicht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Verleiht den Segen des gebündelten Mondlichts.\n\"Eine wässrige, wabernde Kugel, die ein sanftes Licht ausstrahlt.\"" }
entries[210981] = { ["name"] = "Kriegvals Helm", ["text"] = "\"Dieser Helm gehörte dem ersten Irdenen, der sich je abschaltete. Es wäre eine Tragödie, wenn dieses Artefakt verloren ginge.\"" }
entries[210982] = { ["name"] = "Faden der Macht", ["text"] = "Wird beim Aufheben gebunden\nWebt diesen Faden in Euren Umhang des ewigen Potenzials , um Eure Hauptwert dauerhaft um 1 zu erhöhen.\n80 ( 80)" }
