entries[210991] = { ["name"] = "Kleine Schachtel mit Phiolen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Diese kleine Schachtel enthält 6 leere Phiolen. Sie scheinen nicht für Alchemie gedacht zu sein... Wofür können sie sein?\"\n<Zum Öffnen rechtsklicken>" }
entries[210992] = { ["name"] = "Überquellender Traumwächterschatz", ["text"] = "Wird an Kriegsmeute gebunden\n\"Enthält eine Reihe an Belohnungen für jene, die sich als wahre Verbündete der Traumwächter erwiesen haben.\"\n<Zum Öffnen rechtsklicken>" }
