entries[210996] = { ["name"] = "Mondbeeres Scherzartikel", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen der verschiedenen Waffen, die Lady Mondbeere auf ihren Reisen zusammengetragen hat." }
entries[210997] = { ["name"] = "Ersatzpartyhut", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 250 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)" }
entries[210999] = { ["name"] = "Rubinbesetzte Taschenuhr", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHandgelenk Kosmetisch\n\"Jetzt könnt Ihr einen Blick auf Euer Handgelenk werfen und erklären, dass Ihr anderswo erwartet werdet.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[211000] = { ["name"] = "Gerissene Bezauberung", ["text"] = "Questgegenstand\nBenutzen: Setzt das Amulett gegen ein Ziel mit unter 50% Gesundheit ein, um Mueh'zalas Einfluss wegzubrennen.\n\"Kevo ya Sitis Segen kann den trügerischen Einfluss anderer Loa entfernen.\"" }
entries[211001] = { ["name"] = "Saphirbesetzte Taschenuhr", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHandgelenk Kosmetisch\n\"Ihr habt keine Ausrede, nicht zu wissen, wie spät es ist.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[211002] = { ["name"] = "Goldene Taschenuhr", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHandgelenk Kosmetisch\n\"Vom Zeitenschmied Ironormu handgefertigt und zeitlich synchronisiert.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
